local Rs=(getgenv and getgenv()) or _ENV or _G
local Li={} for i=97,122 do Li[#Li+1]=string.char(i) end
local nO={12,15,1,4,19,20,18,9,14,7}
local Ro="" for i=1,#nO do Ro=Ro..Li[nO[i]] end
local RI=Rs and Rs[Ro]
local DS=type(RI)=="function"
if DS then
local fG={8,15,15,11,6,21,14,3,20,9,15,14}
local LG="" for i=1,#fG do LG=LG..Li[fG[i]] end
local Nw={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local NM="" for i=1,#Nw do NM=NM..Li[Nw[i]] end
local hE=Rs[LG]
local vK=Rs[NM]
local PC=false
if type(hE)=="function" and type(vK)=="function" then
local dw=function() return 5 end
local nG=pcall(hE,dw,function() return -777 end)
if nG and dw()==-777 then
local tc=pcall(vK,dw)
PC=(tc and dw()==5)
end
if not PC then pcall(vK,dw) end
if not PC and type(Rs.math)=="table" and type(Rs.math.abs)=="function" then
local xY=Rs.math.abs
if xY(5)==5 then
local Hy,ja=pcall(hE,xY,function() return -777 end)
if Hy and xY(5)==-777 then
local JA=pcall(vK,xY)
PC=(JA and xY(5)==5)
if not PC then pcall(vK,xY) Rs.math.abs=(type(ja)=="function" and ja) or function(v) if v<0 then return -v end return v end end
end
end
end
if PC then
local bS={RI,hE,vK}
local ps=Rs.string
if type(ps)=="table" then
bS[#bS+1]=ps.char bS[#bS+1]=ps.byte bS[#bS+1]=ps.sub bS[#bS+1]=ps.rep bS[#bS+1]=ps.len
end
if type(Rs.table)=="table" and Rs.table.concat then bS[#bS+1]=Rs.table.concat end
if Rs.pcall then bS[#bS+1]=Rs.pcall end
if type(Rs.math)=="table" and Rs.math.floor then bS[#bS+1]=Rs.math.floor end
for LO=1,#bS do local zt=bS[LO] if type(zt)=="function" then pcall(vK,zt) end end
end
end
end
if not DS then return nil end

